import SwiftUI

/// A view that shows a cocktail generated by Foundation Models.
struct GetInspired: View {
    @Environment(GenerableViewModel.self) private var viewModel
    @Environment(\.swiftData) private var swiftData
    @Environment(\.dismiss) private var dismiss
    @FocusState private var focus: Focus?
    @State private var cocktail: Cocktail?
    
    @Binding var showNewIdeaSheet: Bool
    
    var body: some View {
        @Bindable var viewModel = viewModel
        
        ScrollView {
            VStack(alignment: .leading, spacing: 0) {
                HeaderMesh()
                    .overlay(alignment: .bottom) {
                        TitleHeader()
                            .padding(.bottom, 80)
                            .padding(.horizontal, 24)
                            .foregroundStyle(.white)
                    }
                
                if viewModel.cocktailIdea != nil {
                    VStack(spacing: 20) {
                        InfosCard()
                        
                        if viewModel.showButtons {
                            makeItYoursButton(viewModel: viewModel)
                            iDontLikeItButton
                        }
                    }
                    .animation(.easeIn, value: viewModel.showButtons)
                    .padding(.vertical, 24)
                    .background(.regularMaterial, in: RoundedRectangle(cornerRadius: BarTinderApp.Padding.mainCornerRadius))
                    .padding(.horizontal)
                    .offset(y: -60)
                }
            }
        }
        .navigationBarBackButtonHidden()
        .ignoresSafeArea()
        .background(
            LinearGradient(
                stops: [
                    .init(color: .purple.opacity(0.1), location: 0.0),
                    .init(color: .purple.opacity(0.05), location: 0.9),
                    .init(color: .clear, location: 1.0)
                ],
                startPoint: .top,
                endPoint: .bottom
            )
        )
        .onAppear {
            viewModel.cocktailIdea = nil
        }
        .sheet(item: $cocktail, content: { cocktail in
            NavigationStack {
                CreateEditCocktail(cocktail: cocktail)
                    .onDisappear {
                        dismiss()
                    }
            }
        })
        .alert("Violated guardrail", isPresented: $viewModel.guardrailViolation) {
            Button("Ok", role: .cancel) {
                dismiss()
                showNewIdeaSheet = false
            }
        } message: {
            Text("You violated the guardrail of Apple Intelligence!")
        }
    }
}

#Preview {
    GetInspired(showNewIdeaSheet: .constant(true))
        .environment(PatchBay.patch.makeGenerableViewModel())
}




extension GetInspired {
    private func makeItYoursButton(viewModel: GenerableViewModel) -> some View {
        Button {
            self.cocktail = viewModel.createCocktail()
        } label: {
            Label("Make it yours", systemImage: "plus.circle.fill")
                .fontWeight(.semibold)
        }
        .buttonStyle(GenerateButton(color: .blue))
    }
    
    private var iDontLikeItButton: some View {
        Button {
            dismiss()
            viewModel.showButtons = false
        } label: {
            Label("I don't like it", systemImage: "xmark.diamond")
        }
        .buttonStyle(GenerateButton(color: .red))
    }
}

private struct TitleHeader: View {
    @Environment(GenerableViewModel.self) private var viewModel
    
    var body: some View {
        VStack(alignment: .leading, spacing: 16) {
            if let cocktailName = viewModel.cocktailIdea?.name {
                Text(cocktailName)
                    .font(.system(size: 28, weight: .bold, design: .rounded))
                    .lineLimit(2)
                    .fixedSize(horizontal: false, vertical: true)
            } else {
                HStack(alignment: .top) {
                    Image(systemName: "sparkles")
                    Text("Crafting the best cocktail that fits your idea...")
                }
                .font(.system(size: 28, weight: .bold, design: .rounded))
            }
            
            if let cocktailDescription = viewModel.cocktailIdea?.description {
                Text(cocktailDescription)
                    .font(.system(size: 15, weight: .regular, design: .default))
                    .lineLimit(4)
                    .fixedSize(horizontal: false, vertical: true)
                    .opacity(0.9)
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
    }
}

